def portfolio_value(stock_holdings_data, current_market_prices):
    total_portfolio_worth = 0.0
    for stock_ticker_symbol, number_of_shares_owned in stock_holdings_data.items():
        if stock_ticker_symbol in current_market_prices:
            share_price_at_market = current_market_prices[stock_ticker_symbol]
            current_stock_holding_value = number_of_shares_owned * share_price_at_market
            total_portfolio_worth += current_stock_holding_value
    return total_portfolio_worth

